import type { ComponentPropsWithRef, ReactNode } from "react";
import { Empty, EmptyContent, EmptyDescription, EmptyMedia, EmptyTitle } from "@/components/ui/empty";
import { emptyStateCss, emptyStateStyleHref } from "@/components/ui/kalos-empty-state-styles";
import { KalosGlyph, type HugeIcon } from "@/components/ui/kalos-glyph";
import { cn } from "@/lib/utils";

export type { HugeIcon };

export interface KalosEmptyStateProps extends Omit<ComponentPropsWithRef<"div">, "title" | "children"> {
  title: ReactNode;
  text?: ReactNode;
  action?: ReactNode;
  icon?: ReactNode | HugeIcon;
  bare?: boolean;
  tall?: boolean;
}

// File02, Hugeicons Free (MIT). The license is included with the component styles.
const fileIcon = <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.9"
  strokeLinecap="round" strokeLinejoin="round" focusable="false">
  <path d="M8 17H16" />
  <path d="M8 13H12" />
  <path d="M13 2.5V3C13 5.82843 13 7.24264 13.8787 8.12132C14.7574 9 16.1716 9 19 9H19.5M20 10.6569V14C20 17.7712 20 19.6569 18.8284 20.8284C17.6569 22 15.7712 22 12 22C8.22876 22 6.34315 22 5.17157 20.8284C4 19.6569 4 17.7712 4 14V9.45584C4 6.21082 4 4.58831 4.88607 3.48933C5.06508 3.26731 5.26731 3.06508 5.48933 2.88607C6.58831 2 8.21082 2 11.4558 2C12.1614 2 12.5141 2 12.8372 2.11401C12.9044 2.13772 12.9702 2.165 13.0345 2.19575C13.3436 2.34355 13.593 2.593 14.0919 3.09188L18.8284 7.82843C19.4065 8.40649 19.6955 8.69552 19.8478 9.06306C20 9.4306 20 9.83935 20 10.6569Z" />
</svg>;

export function KalosEmptyState({
  title, text, action, icon = fileIcon, bare = false, tall = false, className, ...props
}: KalosEmptyStateProps) {
  return <>
    <style href={emptyStateStyleHref} precedence="default">{emptyStateCss}</style>
    <Empty {...props} className={cn("kalos-empty-state", className)}
      data-bare={bare || undefined} data-tall={tall || undefined}>
      {icon != null && icon !== false && <EmptyMedia aria-hidden="true"><KalosGlyph icon={icon} strokeWidth={1.9} /></EmptyMedia>}
      <EmptyTitle>{title}</EmptyTitle>
      {text != null && text !== false && text !== "" && <EmptyDescription>{text}</EmptyDescription>}
      {action != null && action !== false && action !== "" && <EmptyContent>{action}</EmptyContent>}
    </Empty>
  </>;
}

import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "cn";

function Empty({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="empty"
      className={cn(
        "flex w-full min-w-0 flex-1 flex-col items-center justify-center gap-4 rounded-xl border-dashed p-6 text-center text-balance",
        className,
      )}
      {...props}
    />
  );
}

function EmptyHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="empty-header"
      className={cn("flex max-w-sm flex-col items-center gap-2", className)}
      {...props}
    />
  );
}

const emptyMediaVariants = cva(
  "mb-2 flex shrink-0 items-center justify-center [&_svg]:pointer-events-none [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        default: "bg-transparent",
        icon: "flex size-8 shrink-0 items-center justify-center rounded-lg bg-muted text-foreground [&_svg:not([class*='size-'])]:size-4",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  },
);

function EmptyMedia({
  className,
  variant = "default",
  ...props
}: React.ComponentProps<"div"> & VariantProps<typeof emptyMediaVariants>) {
  return (
    <div
      data-slot="empty-icon"
      data-variant={variant}
      className={cn(emptyMediaVariants({ variant, className }))}
      {...props}
    />
  );
}

function EmptyTitle({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="empty-title"
      className={cn(
        "font-heading text-[13px] font-medium tracking-tight",
        className,
      )}
      {...props}
    />
  );
}

function EmptyDescription({ className, ...props }: React.ComponentProps<"p">) {
  return (
    <div
      data-slot="empty-description"
      className={cn(
        "text-[13px]/relaxed text-muted-foreground [&>a]:underline [&>a]:underline-offset-4 [&>a:hover]:text-primary",
        className,
      )}
      {...props}
    />
  );
}

function EmptyContent({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="empty-content"
      className={cn(
        "flex w-full max-w-sm min-w-0 flex-col items-center gap-2.5 text-[13px] text-balance",
        className,
      )}
      {...props}
    />
  );
}

export {
  Empty,
  EmptyHeader,
  EmptyTitle,
  EmptyDescription,
  EmptyContent,
  EmptyMedia,
};

